{
  "architecture": {
    "services": [
      {
        "name": "calc",
        "path": "services/calc",
        "language": "go",
        "public_interface": {
          "kind": "ui",
          "elements": [
            {
              "page": "Calc",
              "role": "button",
              "name": "Halve"
            },
            {
              "page": "Calc",
              "role": "textbox",
              "name": "Number"
            }
          ]
        }
      }
    ],
    "concepts": [
      {
        "concept": "number ready",
        "block": "given",
        "service": "calc",
        "references": [
          {
            "element": {
              "page": "Calc",
              "role": "textbox",
              "name": "Number"
            }
          }
        ],
        "does": "Clear the Number textbox on page Calc and type the Given step’s numeral into it verbatim, character for character, with no parsing, reformatting, rounding, padding or stripping of leading or trailing characters, so the textbox value is exactly the text the step wrote, and leave it set before the action."
      },
      {
        "concept": "halve",
        "block": "when",
        "service": "calc",
        "intent": "On page Calc, activate the button named \"Halve\" exactly once, and do nothing else: do not type into or otherwise modify the Number textbox, do not activate the button a second time, and do not compute or substitute the halved value yourself. The number already entered in the Number textbox is the input the button acts on."
      },
      {
        "concept": "number result",
        "block": "then",
        "service": "calc",
        "references": [
          {
            "element": {
              "page": "Calc",
              "role": "textbox",
              "name": "Number"
            }
          }
        ],
        "does": "Read the Number textbox value, parse it as a decimal number and assert numeric equality with the expected numeral supplied by the Then step."
      }
    ],
    "terms": []
  }
}
